#include "EqNode.h"
using namespace hub;
static JsonArray endpoints(){auto e=EqNode::enumerator();winrt::com_ptr<IMMDeviceCollection> items;check_hresult(e->EnumAudioEndpoints(eAll,DEVICE_STATEMASK_ALL,items.put()));UINT count{};items->GetCount(&count);JsonArray result;for(UINT i=0;i<count;i++){winrt::com_ptr<IMMDevice> device;items->Item(i,device.put());auto name=EqNode::name(device.get());DWORD state{};device->GetState(&state);JsonObject item;put(item,L"integrated",EqNode::integrated(name));put(item,L"id",EqNode::id(device.get()));put(item,L"name",name);put(item,L"state",(double)state);result.Append(item);}return result;}
int wmain(int argc,wchar_t** argv){winrt::init_apartment(winrt::apartment_type::multi_threaded);if(argc<2)return 2;JsonObject report;try{auto before=endpoints();report.SetNamedValue(L"before",before);if(argc>2&&std::wstring(argv[2])==L"--verify"){
 auto roles=EqNode::physicalRoleDefaults();bool active=false;for(auto const& value:before)if(flag(value.GetObject(),L"integrated")&&((DWORD)num(value.GetObject(),L"state")&DEVICE_STATE_ACTIVE))active=true;
 auto count=EqNode::rename();if(!count)throw hresult_error(E_NOTIMPL,L"No accessible FxSound/Hhub endpoint in this session");put(report,L"renamed",(double)count);EqNode::active(false);auto stopped=endpoints();report.SetNamedValue(L"stopped",stopped);
 for(auto const& value:stopped)if(flag(value.GetObject(),L"integrated")&&((DWORD)num(value.GetObject(),L"state")&DEVICE_STATE_ACTIVE))throw hresult_error(E_FAIL,L"Audio node still active after shutdown");
 EqNode::active(active);report.SetNamedValue(L"restored",endpoints());auto afterRoles=EqNode::physicalRoleDefaults();for(int i=0;i<3;i++)if(!roles[i].empty()&&afterRoles[i]!=roles[i])throw hresult_error(E_FAIL,L"Physical output default changed");
 }put(report,L"ok",true);}catch(hresult_error const& e){put(report,L"ok",false);put(report,L"error",std::wstring(e.message()));}catch(...){put(report,L"ok",false);}write(argv[1],std::wstring(report.Stringify()));return flag(report,L"ok")?0:1;}
